 check(catalog->interaction->common.get()==catalog->common.get(),"all admitted domains share one CommonCatalog projection");
 auto old_gate=CommonStore(initial.seed.common,std::make_shared<const CommonCatalog>(std::move(legacy_common))).validate_common();check(!old_gate.ok&&old_gate.error.original.code=="BaseActorAgeMismatch","legacy BaseActorAgeMismatch remains strict");
 ResidentWorld world;must(world.install(catalog,std::move(initial.seed),true),"real install");auto initial_checkpoint=must(world.checkpoint(),"initial genuine checkpoint");auto cold=read(world,catalog);check(!cold->common.state().actors.find("actor.player")->birth_tick&&cold->common.actor("actor.player")->hp==57,"authored origin does not invent birthday/heal");
 {auto fake=*cold;fake.common.state().actors.find("actor.innkeeper")->birth_tick=-720;auto denied=fake.validate();check(!denied.ok&&denied.error.original.code=="AuthoredActorFoundationIdentityMismatch","authored cold validation rejects a fabricated birthday");}
 advance(world,catalog,moment(0,"1","4"));auto started=service(world,catalog);auto running=read(world,catalog);check(running->world_timeline->boundary_state==PeriodBoundaryState::open,"fractional Open genuine state");check(must(compare_world_moments(std::get<ElapsedRunning>(running->action_elapsed->entries.back().timing).completion_due_at,moment(2,"1","4")),"due compare")==0,"noninteger due preserved");
 auto begin=must(world.begin_run(begin_request(world,"scope.one",started,2)),"begin actual rest run");check(begin.exact_source_moment&&must(compare_world_moments(*begin.exact_source_moment,moment(0,"1","4")),"begin source M")==0,"begin progress exact source");auto first=must(world.resume_run({begin.identity,"scope.one",1,1}),"one half-day actual allowance");check(first.stop==RunStop::awaiting_permit&&first.exact_spent_units.has_value(),"run parks with exact budget");check(must(compare_fractions(first.exact_spent_units->value,must(normalize_fraction("60","1"),"spent60")),"spent compare")==0,"world elapsed charged once despite integer boundary split");check(first.exact_source_moment&&first.identity.tick==first.exact_source_moment->half_day_tick&&must(compare_world_moments(*first.exact_source_moment,moment(1,"1","4")),"progress source M")==0,"fractional progress identity and moment aligned");auto mid=read(world,catalog);check(must(compare_world_moments(must(read_world_moment(mid->common.tick(),*mid->world_timeline),"mid moment"),moment(1,"1","4")),"mid compare")==0,"mid unfinished exact time");check(mid->common.actor("actor.player")->hp==57,"body not applied early");
 auto snapshot=must(world.continuation_snapshot(),"valid actual scope snapshot");check(snapshot&&snapshot->continuation_version==2,"actual HMCN2 scope");auto frozen=must(encode_continuation_snapshot(*snapshot),"encode exact scope");auto thawed=must(decode_continuation_snapshot(frozen),"decode exact scope");auto checkpoint=must(world.checkpoint(),"mid checkpoint");must(inspect_world_checkpoint_selection(checkpoint),"Growth36 exact physical selector");auto bound_bytes=must(bind_continuation_checkpoint(thawed,checkpoint,engineering_slot_capacity_profile()),"HMCB2 binds genuine exact checkpoint");check(!unbind_continuation_checkpoint(bound_bytes,initial_checkpoint,engineering_slot_capacity_profile()).ok,"genuine different checkpoint cannot reuse exact scope");thawed=must(unbind_continuation_checkpoint(bound_bytes,checkpoint,engineering_slot_capacity_profile()),"HMCB2 exact source roundtrip");ResidentWorld restored;must(restored.restore(checkpoint,catalog,thawed),"cold resume actual world/scope");auto again=must(restored.begin_run(begin_request(restored,"scope.two",started,1,true)),"explicit remaining scope begin");auto finished=must(restored.resume_run({again.identity,"scope.two",1,1}),"finish true noninteger due");check(finished.exact_source_moment&&must(compare_world_moments(*finished.exact_source_moment,moment(2,"1","4")),"terminal progress M")==0,"completed progress retains exact source");check(finished.stop==RunStop::completed,"true LifeActivity result stops run");auto end=read(restored,catalog);check(end->common.actor("actor.player")->hp==92&&end->common.actor("actor.player")->fatigue==12&&end->common.state().actors.find("actor.player")->injury==0,"original rest body exactly once");check(end->actor_foundation->character_condition_extensions.applied_receipts.size()==1,"one actual ConditionReceipt");check(end->growth.fixed_service_boundaries.size()==2,"one actual Started and Completed");check(must(compare_world_moments(must(read_world_moment(end->common.tick(),*end->world_timeline),"end moment"),moment(2,"1","4")),"end compare")==0,"completion no ceil delay");
 auto json=must(export_world_state(*end),"whole JSON export");WorldBundle json_world(catalog,must(decode_world_seed(json,*catalog),"whole JSON decode"));must(json_world.validate(),"whole JSON source closure");check(compare_boundary(json,must(export_world_state(json_world),"JSON re-export")).exact(),"all root and nested field orders roundtrip");
 // 冷篡改反例必须在完整世界验证处被拒绝。
 {auto bad=*end;bad.action_elapsed->terminal_bindings.front().terminal_result_ref="forged";std::get<ElapsedTerminal>(bad.action_elapsed->entries.front().timing).outcome_ref="forged";check(!bad.validate().ok,"mutually forged terminal ids rejected");}{auto bad=*end;bad.action_elapsed->fixed_service_transitions.back().terminal_disposition=FixedTerminalDisposition::interrupted;check(!bad.validate().ok,"different original terminal disposition rejected");}{auto bad=*end;auto& completed=bad.growth.fixed_service_boundaries.rows().back().second;for(auto& actor:completed.input_snapshot.actors)if(actor.actor_id=="actor.player"){ExactRestTimeRead time(bad.growth);const auto& head=*bad.actor_foundation->character_condition_extensions.actor_condition_heads.find("actor.player");actor.capability_frames.front()=must(read_authored_rest_capability_at_head(bad.common.state(),*bad.actor_foundation,*bad.catalog->actor_foundation,head,actor.capability_frames.front().purpose_ref,actor.capability_frames.front().captured_at,&bad.growth,&time),"canonical actual post-head frame");}check(!bad.validate().ok,"same-M post-image cannot replace actual before frame");}{auto bad=*end;bad.actor_foundation->character_condition_extensions.applied_receipts={};auto* h=bad.actor_foundation->character_condition_extensions.actor_condition_heads.find("actor.player");h->condition_revision=0;h->latest_receipt_ref.reset();check(!bad.validate().ok,"completed action receipt cannot disappear");}
 // 不先poll也必须撤销被人工advance改动过的旧run许可。
 auto second=service(restored,catalog);auto parked=must(restored.begin_run(begin_request(restored,"scope.three",second,2)),"second run");(void)parked;advance(restored,catalog,moment(2,"1","2"));auto before_resume=must(restored.identity(),"manual stable identity");auto blocked=must(restored.resume_run({before_resume,"scope.three",1,1}),"direct resume without poll");check(blocked.exact_source_moment&&blocked.identity.tick==blocked.exact_source_moment->half_day_tick&&must(compare_world_moments(*blocked.exact_source_moment,moment(2,"1","2")),"blocked progress M")==0,"blocked progress source matches manual stable identity");check(blocked.stop==RunStop::blocked,"manual mutation revokes stale scope");check(must(restored.identity(),"after blocked").revision==before_resume.revision,"blocked scope does not advance");
 // 真实第二次rest把身体恢复到上限，再完成第三次净零rest；缺最后receipt不得靠末态相等漏过。
 advance(restored,catalog,moment(3));check(read(restored,catalog)->world_timeline->boundary_state==PeriodBoundaryState::ready,"integer closing is Ready");
 advance(restored,catalog,moment(4));advance(restored,catalog,moment(4,"1","4"));auto before_zero=read(restored,catalog);check(before_zero->common.actor("actor.player")->hp==100&&before_zero->common.actor("actor.player")->fatigue==0,"second real rest reaches cap");
 auto previous_head=*before_zero->actor_foundation->character_condition_extensions.actor_condition_heads.find("actor.player");service(restored,catalog);advance(restored,catalog,moment(5));advance(restored,catalog,moment(6));advance(restored,catalog,moment(6,"1","4"));auto zero=read(restored,catalog);check(zero->common.actor("actor.player")->hp==100&&zero->common.actor("actor.player")->fatigue==0,"third real rest is net-zero");
 {auto bad=*zero;auto* head=bad.actor_foundation->character_condition_extensions.actor_condition_heads.find("actor.player");check(head->latest_receipt_ref.has_value(),"third actual receipt exists");check(bad.actor_foundation->character_condition_extensions.applied_receipts.erase(head->latest_receipt_ref->result_id),"remove only last actual receipt");*head=previous_head;check(!bad.validate().ok,"net-zero completed rest still requires unique actual receipt");}
 {auto bad=*zero;bad.interaction.events.emplace_back();check(!bad.validate().ok,"empty macro selection rejects actual event todo");}
 auto fourth=service(restored,catalog);auto bounded=must(restored.begin_run(begin_request(restored,"scope.large-permit",fourth,std::numeric_limits<Integer>::max())),"begin original maximum scope without fixed action overflow");auto capped=must(restored.resume_run({bounded.identity,"scope.large-permit",1,std::numeric_limits<Integer>::max()}),"maximum positive permit uses true running due before calendar construction");check(capped.stop==RunStop::completed&&capped.exact_source_moment&&must(compare_world_moments(*capped.exact_source_moment,moment(8,"1","4")),"capped permit M")==0,"maximum scope and permit preserve original allowance and stop at real due");
 // 同一巨大原scope在非零分数起点真实推进、保存、冷恢复；只存原条款，不缩为当前action期限。
