 auto huge_snapshot=must(restored.continuation_snapshot(),"actual huge cold scope");check(huge_snapshot&&huge_snapshot->max_half_days==std::numeric_limits<Integer>::max(),"snapshot does not shrink original scope");auto huge_wire=must(encode_continuation_snapshot(*huge_snapshot),"huge scope HMCN2 encode");auto huge_thawed=must(decode_continuation_snapshot(huge_wire),"huge scope HMCN2 decode");auto huge_checkpoint=must(restored.checkpoint(),"huge scope actual world checkpoint");ResidentWorld huge_restored;must(huge_restored.restore(huge_checkpoint,catalog,huge_thawed),"huge scope actual cold restore");auto huge_again=must(huge_restored.begin_run(begin_request(huge_restored,"scope.large-cold-resumed",fifth,std::numeric_limits<Integer>::max()-1,true)),"huge scope retained terms resume");auto huge_done=must(huge_restored.resume_run({huge_again.identity,"scope.large-cold-resumed",1,std::numeric_limits<Integer>::max()}),"huge restored permit clamps only runtime endpoint");check(huge_done.stop==RunStop::completed&&huge_done.max_half_days==std::numeric_limits<Integer>::max()&&huge_done.exact_source_moment&&must(compare_world_moments(*huge_done.exact_source_moment,moment(10,"1","4")),"huge restored due")==0,"huge cold scope finishes at true noninteger due with original budget");
